with cleaned as (select id, customer_id, device, browser, started_at, country, lower(device) as device_lower from sessions where started_at > to_date('2023-02-16')) select id, customer_id, browser, row_number() over w_hist as event_seq, last_value(browser, true) over w_recent as last_known_browser, last_value(country, true) over w_ordered as last_known_country from cleaned where hour(started_at) between 10 and 15 window w_hist as (partition by country order by started_at, id), w_recent as (partition by device order by started_at, id rows between unbounded preceding and current row), w_ordered as (partition by browser order by started_at, id rows between unbounded preceding and current row);
